public final class AugmentingPath {
    private final Vertex source;
    private final Vertex sink;
    private final int bottleneck;
    private final Vertex[] parents;

    public AugmentingPath(Vertex source, Vertex sink, int bottleneck, Vertex[] parents) {
        this.source = source;
        this.sink = sink;
        this.bottleneck = bottleneck;
        this.parents = parents.clone();
    }

    public Vertex source() {
        return source;
    }

    public Vertex sink() {
        return sink;
    }

    public int bottleneck() {
        return bottleneck;
    }

    public Vertex parentOf(Vertex vertex) {
        return parents[vertex.index()];
    }
}

import java.util.ArrayDeque;
import java.util.Optional;
import java.util.Queue;

public final class BreadthFirstAugmentingPathFinder implements AugmentingPathFinder {
    @Override
    public Optional<AugmentingPath> find(ResidualNetwork network, FlowProblem problem) {
        boolean[] visited = new boolean[network.size()];
        Vertex[] parents = new Vertex[network.size()];
        Vertex[] vertices = network.vertices();
        Queue<Vertex> queue = new ArrayDeque<>();

        queue.add(problem.source());
        visited[problem.source().index()] = true;

        while (!queue.isEmpty()) {
            Vertex current = queue.poll();

            for (Vertex next : vertices) {
                if (visited[next.index()] || !network.hasCapacity(current, next)) {
                    continue;
                }

                parents[next.index()] = current;
                if (next.equals(problem.sink())) {
                    return Optional.of(createPath(network, problem, parents));
                }

                visited[next.index()] = true;
                queue.add(next);
            }
        }

        return Optional.empty();
    }

    private AugmentingPath createPath(ResidualNetwork network, FlowProblem problem, Vertex[] parents) {
        int bottleneck = Integer.MAX_VALUE;

        for (Vertex vertex = problem.sink(); !vertex.equals(problem.source()); vertex = parents[vertex.index()]) {
            Vertex previous = parents[vertex.index()];
            bottleneck = Math.min(bottleneck, network.capacity(previous, vertex));
        }

        return new AugmentingPath(problem.source(), problem.sink(), bottleneck, parents);
    }
}

public final class ResidualNetwork {
    private final int[][] capacities;
    private final Vertex[] vertices;

    public ResidualNetwork(FlowNetwork network) {
        capacities = network.copyCapacities();
        vertices = network.vertices();
    }

    public int size() {
        return capacities.length;
    }

    public boolean hasCapacity(Vertex from, Vertex to) {
        return capacity(from, to) > 0;
    }

    public Vertex vertexAt(int index) {
        return vertices[index];
    }

    public Vertex[] vertices() {
        return vertices.clone();
    }

    public int capacity(Vertex from, Vertex to) {
        return capacities[from.index()][to.index()];
    }

    public void augment(AugmentingPath path) {
        for (Vertex vertex = path.sink(); vertex.index() != path.source().index(); vertex = path.parentOf(vertex)) {
            Vertex previous = path.parentOf(vertex);
            capacities[previous.index()][vertex.index()] -= path.bottleneck();
            capacities[vertex.index()][previous.index()] += path.bottleneck();
        }
    }

    public int[][] snapshot() {
        return IntMatrix.copyOf(capacities);
    }
}

public final class FordFulkersonSolver implements MaxFlowAlgorithm {
    private final AugmentingPathFinder pathFinder;

    public FordFulkersonSolver() {
        this(new BreadthFirstAugmentingPathFinder());
    }

    public FordFulkersonSolver(AugmentingPathFinder pathFinder) {
        if (pathFinder == null) {
            throw new IllegalArgumentException("Path finder must not be null.");
        }
        this.pathFinder = pathFinder;
    }

    @Override
    public MaxFlowResult solve(FlowProblem problem) {
        ResidualNetwork residualNetwork = new ResidualNetwork(problem.network());
        int maxFlow = 0;

        while (true) {
            java.util.Optional<AugmentingPath> path = pathFinder.find(residualNetwork, problem);
            if (path.isEmpty()) {
                return new MaxFlowResult(maxFlow, residualNetwork.snapshot());
            }

            residualNetwork.augment(path.get());
            maxFlow += path.get().bottleneck();
        }
    }
}

final class VertexTraversalState {
    private final Vertex source;
    private final boolean[] visited;
    private final Vertex[] parents;

    VertexTraversalState(int size, Vertex source) {
        this.source = source;
        this.visited = new boolean[size];
        this.parents = new Vertex[size];
        this.visited[source.index()] = true;
    }

    boolean hasVisited(Vertex vertex) {
        return visited[vertex.index()];
    }

    void visit(Vertex vertex, Vertex parent) {
        parents[vertex.index()] = parent;
        visited[vertex.index()] = true;
    }

    Vertex parentOf(Vertex vertex) {
        return parents[vertex.index()];
    }

    AugmentingPath createPath(ResidualNetwork network, Vertex sink) {
        int bottleneck = Integer.MAX_VALUE;

        for (Vertex vertex = sink; !vertex.equals(source); vertex = parentOf(vertex)) {
            Vertex previous = parentOf(vertex);
            bottleneck = Math.min(bottleneck, network.capacity(previous, vertex));
        }

        return new AugmentingPath(source, sink, bottleneck, parents);
    }
}

